export type CreateProfileData = {
    /**
     * 新配置档的 id 与可选显示名。**先落盘再建对象图**：中间崩了文件在那儿、状态是 failed，操作者看得见并可重载。
     */
    body: {
        /**
         * 配置档 id，同时是目录名。
         */
        id: string;
        /**
         * 给人看的名字，可省。
         */
        name?: string;
    };
    path?: never;
    query?: never;
    url: '/profiles';
};

export type CreateProfileErrors = {
    /**
     * 请求无效
     */
    400: ApiError;
    /**
     * 未登录或会话已失效
     */
    401: ApiError;
    /**
     * 冲突。两个判据、三个出口共用这一个状态码，因为判据是同一条「现在不能动」：① 该会话有一次对话正在进行，此时**再发下一条**（`POST /sessions/{id}/messages` 与 `…/messages/stream`）会被拒；② 同一个判据下**删除该会话**也会被拒（`DELETE /sessions/{id}`）—— 那一轮之后的每次落库都会落到「会话不存在」，而已经生成的半轮无处可查；③ 要下线的配置档还占着某个会话，等那轮对话结束后再来。锁在 `core/session/lock.ts` 的 `SessionLock`，由组合根构造并注入每个引擎，**不属于任何一份配置档**。
     */
    409: ApiError;
};

export type CreateProfileError = CreateProfileErrors[keyof CreateProfileErrors];

export type CreateProfileResponses = {
    /**
     * 新建好的配置档。
     */
    201: {
        profile: ProfileRecord;
    };
};

export type CreateProfileResponse = CreateProfileResponses[keyof CreateProfileResponses];

